async function dump(nodeId, label, depth=0) {
  const n = await figma.getNodeByIdAsync(nodeId);
  if (!n) { console.log(label + " -> not found"); return; }
  let info = {id:n.id, type:n.type, name:n.name, visible:n.visible};
  if (n.type === 'FRAME' || n.type === 'COMPONENT' || n.type === 'INSTANCE') {
    info.width = n.width; info.height = n.height;
    info.fill = n.fills;
    if (n.fills && n.fills.length) {
      for (const f of n.fills) {
        if (f.type === 'SOLID') info.fillColor = {r:f.color.r, g:f.color.g, b:f.color.b, a:f.color.a};
      }
    }
    if (n.cornerRadius) info.cornerRadius = n.cornerRadius;
    info.opacity = n.opacity;
    info.effects = n.effects;
  }
  if (n.type === 'TEXT') {
    info.characters = n.characters;
    info.fontName = n.fontName;
    info.fontSize = n.fontSize;
    info.fills = n.fills;
  }
  console.log(JSON.stringify(info));
  if (depth < 3 && ('children' in n)) {
    for (const c of n.children) await dump(c.id, label, depth+1);
  }
}
