function T(parent,text,x,y,size,weight,color){
  const t=figma.createText(); t.characters=text; t.fontName={family:'Plus Jakarta Sans',style:weight};
  t.fontSize=size; t.fills=[{type:'SOLID',color:hex(color)}]; t.x=x; t.y=y; parent.appendChild(t); return t;
}
function hex(h){const n=parseInt(h.slice(1),16);return{r:((n>>16)&255)/255,g:((n>>8)&255)/255,b:(n&255)/255};}
function R(parent,w,h,r,fill,x,y){
  const n=figma.createRectangle(); n.resize(w,h); n.cornerRadius=r;
  n.fills=[{type:'SOLID',color:hex(fill)}]; n.x=x; n.y=y; parent.appendChild(n); return n;
}
function frame(name,x,y,w,h,bg,r){
  const f=figma.createFrame(); f.name=name; f.resize(w,h); f.x=x; f.y=y; f.fills=[];
  if(bg) f.fills=[{type:'SOLID',color:hex(bg)}];
  if(r) f.cornerRadius=r; page.appendChild(f); return f;
}

