async function setIconColor(node,color){
  if(!node) return;
  if(node.type==='VECTOR'){ try{ node.fills=[{type:'SOLID',color:hex(color)}]; }catch(e){} }
  if('children' in node){ for(const ch of node.children) await setIconColor(ch,color); }
}
function hex(h){ const s=h.replace('#',''); return {r:parseInt(s.substr(0,2),16)/255,g:parseInt(s.substr(2,2),16)/255,b:parseInt(s.substr(4,2),16)/255}; }

async function makeText(parent,str,x,y,size,weight,color){
  const t=figma.createText(); await figma.loadFontAsync({family:'Plus Jakarta Sans',style:weight});
  t.fontName={family:'Plus Jakarta Sans',style:weight};
  t.characters=str; t.x=x; t.y=y; t.fontSize=size; t.fills=[{type:'SOLID',color:hex(color)}];
  parent.appendChild(t); return t;
}

