const iconMap=[{id:'2:2',label:'Home'},{id:'2:3',label:'Analytics'},{id:'2:4',label:'Cards'},{id:'2:5',label:'Profile'}];
async function makeTabBar(selectedIndex, name){
  const bar=figma.createComponent();
  bar.name=name; bar.resize(375,84); bar.x=1200; bar.y=100+selectedIndex*110;
  const bg=figma.createRectangle(); bg.name='bg'; bg.resize(375,84); bg.fills=[{type:'SOLID',color:hex('#FFFFFF')}]; bar.appendChild(bg);
  const topLine=figma.createRectangle(); topLine.name='topline'; topLine.resize(375,1); topLine.fills=[{type:'SOLID',color:hex('#EEEEF5')}]; bar.appendChild(topLine);
  const w=375/4;
  for(let i=0;i<4;i++){
    const item=figma.createFrame(); item.name=iconMap[i].label+'Tab'; item.resize(w,84); item.x=i*w; item.y=0; item.fills=[]; bar.appendChild(item);
    const src=await figma.getNodeByIdAsync(iconMap[i].id);
    const ic=src.createInstance(); ic.x=w/2-12; ic.y=14; item.appendChild(ic);
    await setIconColor(ic, i===selectedIndex?brand:gray);
    const active=figma.createRectangle(); active.name='indicator'; active.resize(40,3); active.x=w/2-20; active.y=6; active.cornerRadius=3;
    active.fills= i===selectedIndex?[{type:'SOLID',color:hex(brand)}]:[]; item.appendChild(active);
    await makeText(item,iconMap[i].label,w/2-24,i===selectedIndex?46:43,12,i===selectedIndex?'SemiBold':'Medium', i===selectedIndex?'#000000':'#A9A9BD').then(t=>{});
  }
  return bar;
}

