function txt(text,x,y,w,h,size,weight,color,align) {
  const t = figma.createText();
  t.characters = text; t.x=x; t.y=y; t.resize(w,h);
  t.fontName = {family:'Plus Jakarta Sans', style:weight};
  t.fontSize = size; t.fills=[color];
  if (align==='center'){t.textAlignHorizontal='CENTER'; t.textAlignVertical='CENTER';}
  if (align==='right'){t.textAlignHorizontal='RIGHT'; t.textAlignVertical='CENTER';}
  return t;
}
async function inst(id,px,py,pw,ph,parent){
  const c = await figma.getNodeByIdAsync(id);
  const i = c.createInstance();
  i.x=px; i.y=py;
  if(pw){i.resize(pw,ph);}
  if(parent){parent.appendChild(i);}
  return i;
}
function frame(x,y,w,h,name){
  const f = figma.createFrame(); f.name=name;
  f.layoutMode='NONE'; f.x=x; f.y=y; f.resize(w,h);
  f.fills=[W]; f.clipsContent=true; return f;
}
function chip(x,y,w,h,label,selected){
  const c = frame(x,y,w,h,'chip');
