async function setTab(nodeId, home, anal, card, prof, cur){
  const tb=await figma.getNodeByIdAsync(nodeId);
  if(!tb){ return; }
  const dests={};
  // iterate children/tabs
  for(const t of tb.children){
    const nm=t.name;
    let dest=null;
    if(nm.toLowerCase().includes('home')) dest=home;
    else if(nm.toLowerCase().includes('analytics')) dest=anal;
    else if(nm.toLowerCase().includes('card')) dest=card;
    else if(nm.toLowerCase().includes('profile')) dest=prof;
    if(dest){ t.reactions=[{trigger:{type:'ON_CLICK'}, actions:[{type:'NODE', destinationId:String(dest), navigation:'NAVIGATE', transition:{type:'DISSOLVE', duration:200, easing:{type:'EASE_IN_AND_OUT'}}}]}]; }
  }
}
