async function addTabRx(frameId, tabs){
  const comp=await figma.getNodeByIdAsync(frameId);
  if(!comp){ console.log('MISSING TABBAR',frameId); return; }
  for(const t of comp.children){
    const dest=tabs[t.name];
    if(dest){ t.reactions=[{trigger:{type:'ON_CLICK'}, actions:[{type:'NODE',destinationId:String(dest),navigation:'NAVIGATE',transition:{type:'DISSOLVE',duration:200,easing:{type:'EASE_IN_AND_OUT'}}}]}]; }
  }
  console.log('tabbed',frameId);
}
